```c++
template <int N>
struct Factorial {
  static const int value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
  static const int value = 1;
};

int main() {
  constexpr int result = Factorial<5>::value; // Compile-time calculation
  std::cout << result << std::endl; // Output: 120
  return 0;
}
